          <div class="hp-arrow ${dir}">${icon(dir === 'increase' ? 'arrow-up-right' : dir === 'decrease' ? 'arrow-down-right' : 'equal')}<span>${dir === 'hold' ? 'Hold' : fmtPct(opt.priceChangePct, 1, true)}</span></div>
