      const row = map.get(key) ?? { month: key, revenue: 0, grossProfit: 0, units: 0, weeks: 0 };
      row.revenue += w.revenue;
      row.grossProfit += w.grossProfit;
      row.units += w.units;
      row.weeks += 1;
      map.set(key, row);
