    const currentProfit = rows.reduce((s, r) => s + r.currentProfit, 0);
    const recommendedProfit = rows.reduce((s, r) => s + r.recommendedProfit, 0);
    const avgChange = rows.length ? rows.reduce((s, r) => s + r.priceChangePct, 0) / rows.length : 0;
