  __exports.getPortfolioRecommendations = getPortfolioRecommendations;
  __exports.isOpportunity = isOpportunity;
  __exports.getOpportunityKPIs = getOpportunityKPIs;
  __exports.getCategoryOpportunities = getCategoryOpportunities;
  __exports.getTopOpportunities = getTopOpportunities;
